package com.mzfuture.entire.gitsync.service.impl;

import cn.hutool.core.io.FileUtil;
import com.mzfuture.entire.config.GitProperties;
import com.mzfuture.entire.gitsync.dto.response.GitStatusDTO;
import com.mzfuture.entire.gitsync.dto.response.PullResult;
import com.mzfuture.entire.gitsync.service.GitOperationService;
import com.mzfuture.entire.common.exception.Errors;
import lombok.extern.slf4j.Slf4j;
import org.eclipse.jgit.api.CloneCommand;
import org.eclipse.jgit.api.FetchCommand;
import org.eclipse.jgit.api.Git;
import org.eclipse.jgit.api.PullCommand;
import org.eclipse.jgit.api.errors.GitAPIException;
import org.eclipse.jgit.lib.Ref;
import org.eclipse.jgit.lib.Repository;
import org.eclipse.jgit.revwalk.RevCommit;
import org.eclipse.jgit.transport.CredentialsProvider;
import org.eclipse.jgit.transport.RefSpec;
import org.eclipse.jgit.transport.UsernamePasswordCredentialsProvider;
import org.springframework.stereotype.Service;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;
import java.util.stream.Collectors;

/// Git operation service implementation
@Slf4j
@Service
public class GitOperationServiceImpl implements GitOperationService {

    private final GitProperties gitProperties;

    // Repository operation lock, preventing concurrent operations on the same repository
    private final ConcurrentHashMap<Long, ReentrantLock> repoLocks = new ConcurrentHashMap<>();

    public GitOperationServiceImpl(GitProperties gitProperties) {
        this.gitProperties = gitProperties;
    }

    @Override
    public String cloneRepository(Long repoId, String authUrl, String branch) {
        return cloneRepository(repoId, authUrl, branch, -1);
    }

    @Override
    public String cloneRepository(Long repoId, String authUrl, String branch, int depth) {
        ReentrantLock lock = getRepoLock(repoId);
        lock.lock();
        try {
            String localPath = getLocalRepositoryPath(repoId);
            File repoDir = new File(localPath);

            // If directory already exists, delete first
            if (repoDir.exists()) {
                FileUtil.del(repoDir);
            }

            // Create directory
            repoDir.mkdirs();

            int effectiveDepth = depth < 0 ? gitProperties.getCloneDepth() : depth;
            log.info("Starting to clone repository: repoId={}, branch={}, path={}, depth={}", repoId, branch, localPath, effectiveDepth);

            // Parse REDACTED for authentication
            CredentialsProvider credentials = parseCredentials(authUrl);

            CloneCommand clone = Git.cloneRepository()
                    .setURI(authUrl)
                    .setDirectory(repoDir)
                    .setBranch(branch)
                    .setBranchesToClone(List.of("refs/heads/" + branch))
                    .setTimeout(gitProperties.getTimeoutSeconds());
            if (effectiveDepth > 0) {
                clone.setDepth(effectiveDepth);
            }

            if (credentials != null) {
                clone.setCredentialsProvider(credentials);
            }

            clone.call();

            log.info("Repository cloned successfully: repoId={}, path={}", repoId, localPath);
            return localPath;

        } catch (GitAPIException e) {
            log.error("Failed to clone repository: repoId={}, error={}", repoId, e.getMessage(), e);
            throw Errors.INTERNAL_ERROR.toException("Failed to clone repository: " + e.getMessage());
        } finally {
            lock.unlock();
        }
    }

    @Override
    public PullResult pullRepository(Long repoId, String authUrl, String branch) {
        ReentrantLock lock = getRepoLock(repoId);
        lock.lock();
        try {
            String localPath = getLocalRepositoryPath(repoId);
            File repoDir = new File(localPath);

            if (!repoDir.exists()) {
                throw Errors.INTERNAL_ERROR.toException("Local repository does not exist: " + localPath);
            }

            log.info("Starting to pull repository updates: repoId={}, branch={}", repoId, branch);

            // Parse REDACTED for authentication
            CredentialsProvider credentials = parseCredentials(authUrl);

            try (Git git = Git.open(repoDir)) {
                // First checkout target branch
                git.checkout().setName(branch).call();

                // Pull updates
                PullCommand pull = git.pull()
                        .setRemoteBranchName(branch)
                        .setTimeout(gitProperties.getTimeoutSeconds());

                if (credentials != null) {
                    pull.setCredentialsProvider(credentials);
                }

                org.eclipse.jgit.api.PullResult pullResult = pull.call();

                // Get latest commit information
                RevCommit latestCommit = getLatestCommit(git);

                boolean hasUpdate = pullResult.getMergeResult() != null
                        && pullResult.getMergeResult().getMergeStatus().isSuccessful();

                log.info("Repository pull completed: repoId={}, hasUpdate={}", repoId, hasUpdate);

                return PullResult.builder()
                        .updated(hasUpdate)
                        .commitId(latestCommit != null ? latestCommit.getName() : null)
                        .commitMessage(latestCommit != null ? latestCommit.getShortMessage() : null)
                        .author(latestCommit != null ? latestCommit.getAuthorIdent().getName() : null)
                        .commitTime(latestCommit != null ? latestCommit.getCommitTime() * 1000L : null)
                        .build();
            }

        } catch (IOException | GitAPIException e) {
            log.error("Failed to pull repository: repoId={}, error={}", repoId, e.getMessage(), e);
            throw Errors.INTERNAL_ERROR.toException("Failed to pull repository: " + e.getMessage());
        } finally {
            lock.unlock();
        }
    }

    @Override
    public GitStatusDTO getRepositoryStatus(Long repoId) {
        String localPath = getLocalRepositoryPath(repoId);
        File repoDir = new File(localPath);

        GitStatusDTO status = new GitStatusDTO();
        status.setRepoId(repoId);
        status.setLocalPath(localPath);
        status.setExists(repoDir.exists() && new File(localPath + "/.git").exists());

        if (!status.getExists()) {
            return status;
        }

        try (Git git = Git.open(repoDir)) {
            Repository repository = git.getRepository();

            // Get current branch
            Ref head = repository.exactRef("HEAD");
            if (head != null && head.isSymbolic()) {
                String branchName = Repository.shortenRefName(head.getTarget().getName());
                status.setCurrentBranch(branchName);
            }

            // Get latest commit
            RevCommit latestCommit = getLatestCommit(git);
            if (latestCommit != null) {
                status.setCommitId(latestCommit.getName());
                status.setCommitMessage(latestCommit.getShortMessage());
                status.setLastCommitTime(latestCommit.getCommitTime() * 1000L);
            }

        } catch (IOException e) {
            log.warn("Failed to get repository status: repoId={}, error={}", repoId, e.getMessage());
        }

        return status;
    }

    @Override
    public boolean isRepositoryExists(Long repoId) {
        String localPath = getLocalRepositoryPath(repoId);
        File repoDir = new File(localPath);
        File gitDir = new File(localPath + "/.git");
        return repoDir.exists() && gitDir.exists();
    }

    @Override
    public boolean isShallow(Long repoId) {
        return new File(getLocalRepositoryPath(repoId), ".git/shallow").exists();
    }

    @Override
    public String getLocalRepositoryPath(Long repoId) {
        String dataPath = gitProperties.getDataPath();
        // Ensure path ends with /
        if (!dataPath.endsWith("/") && !dataPath.endsWith("\\")) {
            dataPath = dataPath + "/";
        }
        return dataPath + repoId;
    }

    @Override
    public boolean deleteRepository(Long repoId) {
        ReentrantLock lock = getRepoLock(repoId);
        lock.lock();
        try {
            String localPath = getLocalRepositoryPath(repoId);
            File repoDir = new File(localPath);

            if (!repoDir.exists()) {
                return true;
            }

            log.info("Deleting local repository: repoId={}, path={}", repoId, localPath);
            return FileUtil.del(repoDir);

        } finally {
            lock.unlock();
        }
    }

    @Override
    public void fetchBranches(Long repoId, String authUrl, List<String> branchNames) {
        if (branchNames == null || branchNames.isEmpty()) {
            return;
        }
        ReentrantLock lock = getRepoLock(repoId);
        lock.lock();
        try {
            String localPath = getLocalRepositoryPath(repoId);
            File repoDir = new File(localPath);
            if (!repoDir.exists() || !new File(repoDir, ".git").exists()) {
                throw Errors.INTERNAL_ERROR.toException("Local repository does not exist: " + localPath);
            }
            CredentialsProvider credentials = parseCredentials(authUrl);
            List<RefSpec> refSpecs = new ArrayList<>();
            for (String branch : branchNames) {
                // Force ("+"): a rewritten/force-pushed remote branch must replace the local copy
                refSpecs.add(new RefSpec("+refs/heads/" + branch + ":refs/heads/" + branch));
            }
            try (Git git = Git.open(repoDir)) {
                FetchCommand fetch = git.fetch()
                        .setRemote("origin")
                        .setRefSpecs(refSpecs)
                        .setTimeout(gitProperties.getTimeoutSeconds());
                if (credentials != null) {
                    fetch.setCredentialsProvider(credentials);
                }
                fetch.call();
                log.info("Fetch branches completed: repoId={}, branches={}", repoId, branchNames.size());
            }
        } catch (IOException | GitAPIException e) {
            log.error("Failed to fetch branches: repoId={}, error={}", repoId, e.getMessage(), e);
            throw Errors.INTERNAL_ERROR.toException("Failed to fetch branches: " + e.getMessage());
        } finally {
            lock.unlock();
        }
    }

    @Override
    public void fetchRefSpecs(Long repoId, String authUrl, List<String> refSpecs) {
        if (refSpecs == null || refSpecs.isEmpty()) {
            return;
        }
        ReentrantLock lock = getRepoLock(repoId);
        lock.lock();
        try {
            String localPath = getLocalRepositoryPath(repoId);
            File repoDir = new File(localPath);
            if (!repoDir.exists() || !new File(repoDir, ".git").exists()) {
                throw Errors.INTERNAL_ERROR.toException("Local repository does not exist: " + localPath);
            }
            CredentialsProvider credentials = parseCredentials(authUrl);
            List<RefSpec> specs = refSpecs.stream().map(RefSpec::new).toList();
            try (Git git = Git.open(repoDir)) {
                FetchCommand fetch = git.fetch()
                        .setRemote("origin")
                        .setRefSpecs(specs)
                        .setRemoveDeletedRefs(true)
                        .setTimeout(gitProperties.getTimeoutSeconds());
                if (credentials != null) {
                    fetch.setCredentialsProvider(credentials);
                }
                fetch.call();
                log.info("Fetch refspecs completed: repoId={}, refSpecs={}", repoId, refSpecs);
            }
        } catch (IOException | GitAPIException e) {
            log.error("Failed to fetch refspecs: repoId={}, error={}", repoId, e.getMessage(), e);
            throw Errors.INTERNAL_ERROR.toException("Failed to fetch refs: " + e.getMessage());
        } finally {
            lock.unlock();
        }
    }

    @Override
    public List<String> listRemoteRefs(String authUrl, String prefix) {
        try {
            CredentialsProvider credentials = parseCredentials(authUrl);
            // heads=false and tags=false means no filtering: every advertised ref is returned
            Collection<Ref> refs = Git.lsRemoteRepository()
                    .setRemote(authUrl)
                    .setCredentialsProvider(credentials)
                    .setHeads(false)
                    .setTags(false)
                    .setTimeout(gitProperties.getTimeoutSeconds())
                    .call();
            return refs.stream()
                    .map(Ref::getName)
                    .filter(name -> prefix == null || name.startsWith(prefix))
                    .sorted()
                    .collect(Collectors.toList());
        } catch (GitAPIException e) {
            log.error("Failed to list remote refs: prefix={}, error={}", prefix, e.getMessage(), e);
            throw Errors.INTERNAL_ERROR.toException("Failed to list remote refs: " + e.getMessage());
        }
    }

    @Override
    public List<String> listRemoteBranches(String authUrl) {
        try {
            CredentialsProvider credentials = parseCredentials(authUrl);
            Collection<Ref> refs = Git.lsRemoteRepository()
                    .setRemote(authUrl)
                    .setCredentialsProvider(credentials)
                    .setHeads(true)
                    .setTags(false)
                    .setTimeout(gitProperties.getTimeoutSeconds())
                    .call();

            return refs.stream()
                    .map(ref -> Repository.shortenRefName(ref.getName()))
                    .sorted()
                    .collect(Collectors.toList());
        } catch (GitAPIException e) {
            log.error("Failed to get remote branch list: error={}", e.getMessage(), e);
            throw Errors.INTERNAL_ERROR.toException("Failed to get remote branch list: " + e.getMessage());
        }
    }

    /// Get repository operation lock
    private ReentrantLock getRepoLock(Long repoId) {
        return repoLocks.computeIfAbsent(repoId, k -> new ReentrantLock());
    }

    /// Parse authentication information
    private CredentialsProvider parseCredentials(String authUrl) {
        // Parse REDACTED from URL
        // Format: REDACTED or https://REDACTED@host/path
        try {
            java.net.URL url = new java.net.URL(authUrl);
            String userInfo = url.getUserInfo();
            if (userInfo != null && !userInfo.isEmpty()) {
                String[] parts = userInfo.split(":");
                if (parts.length >= 2) {
                    // oauth2:REDACTED format
                    return new UsernamePasswordCredentialsProvider(parts[0], parts[1]);
                } else {
                    // Token-only format
                    return new UsernamePasswordCredentialsProvider(userInfo, "");
                }
            }
        } catch (java.net.MalformedURLException e) {
            log.warn("Failed to parse URL: {}", authUrl);
        }
        return null;
    }

    /// Get latest commit
    private RevCommit getLatestCommit(Git git) throws IOException {
        try {
            Iterable<RevCommit> commits = git.log().setMaxCount(1).call();
            for (RevCommit commit : commits) {
                return commit;
            }
        } catch (GitAPIException e) {
            log.warn("Failed to get latest commit: {}", e.getMessage());
        }
        return null;
    }
}

package com.mzfuture.entire.gitsync.service.impl;

import cn.hutool.core.util.StrUtil;
import com.mzfuture.entire.config.GitProperties;
import com.mzfuture.entire.gitrepo.entity.Repo;
import com.mzfuture.entire.gitrepo.enums.RepositoryPlatform;
import com.mzfuture.entire.gitrepo.repository.RepoRepository;
import com.mzfuture.entire.gitsync.dto.request.GitSyncParams;
import com.mzfuture.entire.gitsync.dto.request.TokenValidateParams;
import com.mzfuture.entire.gitsync.dto.response.GitBranchesDTO;
import com.mzfuture.entire.gitsync.dto.response.GitSyncResult;
import com.mzfuture.entire.gitsync.dto.response.TokenValidateResult;
import com.mzfuture.entire.gitsync.dto.response.PullResult;
import com.mzfuture.entire.gitsync.enums.GitSyncStatus;
import com.mzfuture.entire.gitsync.adapter.GitPlatformAdapter;
import com.mzfuture.entire.gitsync.service.GitOperationService;
import com.mzfuture.entire.gitsync.service.GitSyncService;
import com.mzfuture.entire.common.exception.Errors;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.util.List;
import java.util.Map;
import java.util.function.Supplier;
import java.util.stream.Collectors;

/// Git sync service implementation
@Slf4j
@Service
public class GitSyncServiceImpl implements GitSyncService {

    private final RepoRepository repoRepository;
    private final GitOperationService gitOperationService;
    private final GitProperties gitProperties;
    private final Map<RepositoryPlatform, GitPlatformAdapter> platformAdapters;

    public GitSyncServiceImpl(
            RepoRepository repoRepository,
            GitOperationService gitOperationService,
            GitProperties gitProperties,
            List<GitPlatformAdapter> adapters) {
        this.repoRepository = repoRepository;
        this.gitOperationService = gitOperationService;
        this.gitProperties = gitProperties;
        this.platformAdapters = adapters.stream()
                .collect(Collectors.toMap(GitPlatformAdapter::getPlatform, adapter -> adapter));
    }

    @Override
    public GitSyncResult syncRepository(GitSyncParams params) {
        // 1. Match repository exactly by webUrl
        Repo repo = repoRepository.findByWebUrl(params.getWebUrl())
                .orElseThrow(() -> Errors.NOT_FOUND.toException("Repository not found: " + params.getWebUrl()));

        // 2. Execute sync (using global default depth)
        return doSync(repo, params.getAccessToken(), params.getBranch(), -1);
    }

    @Override
    public GitSyncResult syncRepositoryById(Long repoId) {
        Repo repo = repoRepository.findById(repoId)
                .orElseThrow(() -> Errors.NOT_FOUND.toException("Repository does not exist: " + repoId));
        return doSync(repo, null, null, -1);
    }

    @Override
    public GitSyncResult syncRepositoryById(Long repoId, String branch, int cloneDepth) {
        Repo repo = repoRepository.findById(repoId)
                .orElseThrow(() -> Errors.NOT_FOUND.toException("Repository does not exist: " + repoId));
        return doSync(repo, null, branch, cloneDepth);
    }

    /// Execute sync operation; cloneDepth < 0 means use global default depth
    private GitSyncResult doSync(Repo repo, String requestToken, String requestBranch, int cloneDepth) {
        Long repoId = repo.getId();
        String repoName = repo.getName();
        String webUrl = repo.getWebUrl();
        RepositoryPlatform platform = repo.getPlatform();

        // Check if platform is supported
        GitPlatformAdapter adapter = platformAdapters.get(platform);
        if (adapter == null) {
            throw Errors.INTERNAL_ERROR.toException("Unsupported platform type: " + platform);
        }

        // Prefer token from request, otherwise use token from database
        String accessToken = StrUtil.isNotBlank(requestToken) ? requestToken : repo.getAccessToken();
        if (StrUtil.isBlank(accessToken)) {
            throw Errors.INTERNAL_ERROR.toException("Access token cannot be empty");
        }

        // Determine branch (use default branch when requestBranch is empty and cloneDepth is not specified)
        String branch = StrUtil.isNotBlank(requestBranch) ? requestBranch : gitProperties.getDefaultBranch();

        // Build auth URL
        String authUrl = adapter.buildAuthUrl(webUrl, accessToken);

        log.info("Starting repository sync: repoId={}, name={}, platform={}, branch={}",
                repoId, repoName, platform, branch);

        // Determine if clone or pull
        boolean exists = gitOperationService.isRepositoryExists(repoId);

        GitSyncResult result = new GitSyncResult();
        result.setRepoId(repoId);
        result.setRepoName(repoName);
        result.setBranch(branch);
        result.setLocalPath(gitOperationService.getLocalRepositoryPath(repoId));
        result.setSyncTime(System.currentTimeMillis());

        try {
            if (exists) {
                // Execute pull (with retry)
                PullResult pullResult = executeWithRetry(() ->
                        gitOperationService.pullRepository(repoId, authUrl, branch));

                result.setStatus(GitSyncStatus.SUCCESS.name());
                result.setHasUpdate(pullResult.isUpdated());
                result.setCommitId(pullResult.getCommitId());
                result.setCommitMessage(pullResult.getCommitMessage());

                log.info("Repository sync successful (pull): repoId={}, hasUpdate={}",
                        repoId, pullResult.isUpdated());

            } else {
                // Execute clone (with retry); cloneDepth < 0 uses default depth
                int depth = cloneDepth < 0 ? gitProperties.getCloneDepth() : cloneDepth;
                final int finalDepth = depth;
                executeWithRetry(() -> {
                    gitOperationService.cloneRepository(repoId, authUrl, branch, finalDepth);
                    return null;
                });

                // Get repository status
                var status = gitOperationService.getRepositoryStatus(repoId);

                result.setStatus(GitSyncStatus.SUCCESS.name());
                result.setHasUpdate(true);
                result.setCommitId(status.getCommitId());
                result.setCommitMessage(status.getCommitMessage());

                log.info("Repository sync successful (clone): repoId={}, path={}",
                        repoId, result.getLocalPath());
            }

        } catch (Exception e) {
            log.error("Repository sync failed: repoId={}, error={}", repoId, e.getMessage(), e);

            result.setStatus(GitSyncStatus.FAILED.name());
            result.setErrorMessage(e.getMessage());
            result.setHasUpdate(false);

            throw Errors.INTERNAL_ERROR.toException("Repository sync failed: " + e.getMessage());
        }

        return result;
    }

    /// Execute operation with retry
    private <T> T executeWithRetry(Supplier<T> operation) {
        int maxRetries = gitProperties.getRetryCount();
        int attempt = 0;
        Exception lastException = null;

        while (attempt <= maxRetries) {
            try {
                if (attempt > 0) {
                    log.info("Retry attempt {}...", attempt);
                    // Wait 1 second before retry
                    Thread.sleep(1000);
                }
                return operation.get();
            } catch (Exception e) {
                lastException = e;
                attempt++;
                log.warn("Operation failed (attempt {}): {}", attempt, e.getMessage());
            }
        }

        throw Errors.INTERNAL_ERROR.toException(
                "Operation failed after " + maxRetries + " retries: " + lastException.getMessage());
    }

    @Override
    public GitBranchesDTO getBranches(Long repoId) {
        Repo repo = repoRepository.findById(repoId)
                .orElseThrow(() -> Errors.NOT_FOUND.toException("Repository does not exist: " + repoId));

        GitPlatformAdapter adapter = platformAdapters.get(repo.getPlatform());
        if (adapter == null) {
            throw Errors.INTERNAL_ERROR.toException("Unsupported platform type: " + repo.getPlatform());
        }

        if (StrUtil.isBlank(repo.getAccessToken())) {
            throw Errors.INTERNAL_ERROR.toException("Access token cannot be empty");
        }

        String authUrl = adapter.buildAuthUrl(repo.getWebUrl(), repo.getAccessToken());

        List<String> branches = gitOperationService.listRemoteBranches(authUrl);

        GitBranchesDTO result = new GitBranchesDTO();
        result.setRepoId(repoId);
        result.setBranches(branches);
        return result;
    }

    @Override
    public GitSyncResult syncRepositoryAllBranchesForCheckpoint(Long repoId, String metadataBranch, int cloneDepth) {
        Repo repo = repoRepository.findById(repoId)
                .orElseThrow(() -> Errors.NOT_FOUND.toException("Repository does not exist: " + repoId));
        GitPlatformAdapter adapter = platformAdapters.get(repo.getPlatform());
        if (adapter == null) {
            throw Errors.INTERNAL_ERROR.toException("Unsupported platform type: " + repo.getPlatform());
        }
        if (StrUtil.isBlank(repo.getAccessToken())) {
            throw Errors.INTERNAL_ERROR.toException("Access token cannot be empty");
        }
        String authUrl = adapter.buildAuthUrl(repo.getWebUrl(), repo.getAccessToken());
        List<String> remoteBranches = gitOperationService.listRemoteBranches(authUrl);
        if (remoteBranches == null || remoteBranches.isEmpty()) {
            throw Errors.INTERNAL_ERROR.toException("No remote branches");
        }

        GitSyncResult result = new GitSyncResult();
        result.setRepoId(repoId);
        result.setRepoName(repo.getName());
        result.setBranch(metadataBranch);
        result.setLocalPath(gitOperationService.getLocalRepositoryPath(repoId));
        result.setSyncTime(System.currentTimeMillis());

        boolean exists = gitOperationService.isRepositoryExists(repoId);
        int depth = cloneDepth < 0 ? gitProperties.getCloneDepth() : cloneDepth;
        if (exists && depth == 0 && gitOperationService.isShallow(repoId)) {
            // Full history is required (commit walk, per-line blame) but an older clone is shallow: re-clone
            log.info("checkpoint sync: local clone is shallow but full history is required, re-cloning: repoId={}", repoId);
            gitOperationService.deleteRepository(repoId);
            exists = false;
        }
        try {
            if (exists) {
                gitOperationService.fetchBranches(repoId, authUrl, remoteBranches);
                result.setStatus(GitSyncStatus.SUCCESS.name());
                result.setHasUpdate(true);
                log.info("checkpoint all branches fetch completed: repoId={}, branches={}", repoId, remoteBranches.size());
            } else {
                String cloneBranch = remoteBranches.contains(metadataBranch) ? metadataBranch : remoteBranches.get(0);
                executeWithRetry(() -> {
                    gitOperationService.cloneRepository(repoId, authUrl, cloneBranch, depth);
                    return null;
                });
                gitOperationService.fetchBranches(repoId, authUrl, remoteBranches);
                result.setStatus(GitSyncStatus.SUCCESS.name());
                result.setHasUpdate(true);
                log.info("checkpoint clone + all branches fetch completed: repoId={}, cloneBranch={}, branches={}",
                        repoId, cloneBranch, remoteBranches.size());
            }
        } catch (Exception e) {
            log.error("checkpoint all branches sync failed: repoId={}, error={}", repoId, e.getMessage(), e);
            result.setStatus(GitSyncStatus.FAILED.name());
            result.setErrorMessage(e.getMessage());
            result.setHasUpdate(false);
            throw Errors.INTERNAL_ERROR.toException("checkpoint all branches sync failed: " + e.getMessage());
        }
        return result;
    }

    @Override
